		if str(rec.get("decision_type", "")) != "movement":
			continue
		var ctx = rec.get("context", {})
		var uid = str(rec.get("unit_id", ""))
		if found.has(uid):
			continue
		var cards = rec.get("candidates", [])
		var chosen = int(rec.get("chosen_index", 0))
		var desc = str(cards[chosen].get("description", "")) if chosen < cards.size() else ""
		found[uid] = {"earmark": str(ctx.get("earmark", "")), "pass": str(ctx.get("assigned_by", "")), "desc": desc}
GameState.set_meta("pm3_control_arm", found)
return found.size()

var a = GameState.get_meta("pm3_plan_arm", {})
var b = GameState.get_meta("pm3_control_arm", {})
var earmarked = []
for uid in a:
	if not str(a[uid].get("earmark", "")).is_empty():
		earmarked.append(uid)
var control_earmarks = 0
for uid in b:
	if not str(b[uid].get("earmark", "")).is_empty():
		control_earmarks += 1
var differed = 0
for uid in earmarked:
	if b.has(uid) and str(a[uid].get("pass", "")) + "|" + str(a[uid].get("desc", "")) != str(b[uid].get("pass", "")) + "|" + str(b[uid].get("desc", "")):
		differed += 1
print("SCENARIO pm3 earmarked_units=%d control_earmark_records=%d differed_vs_control=%d" % [earmarked.size(), control_earmarks, differed])
for uid in earmarked:
	print("SCENARIO pm3   %s earmark=%s plan[%s|%s] control[%s|%s]" % [uid, a[uid]["earmark"], a[uid]["pass"], a[uid]["desc"], str(b.get(uid, {}).get("pass", "-")), str(b.get(uid, {}).get("desc", "-"))])
if control_earmarks != 0:
	return -1
return earmarked.size()
